{
  "application": "data-visualization",
  "case_id": "case-ecommerce-platform-architecture-3tier-12services",
  "language": "en",
  "style": {
    "theme": "data-dense",
    "audience": "team-internal",
    "tone": "technical, structured, detailed"
  },
  "goal": [
    {
      "id": "layered-service-topology",
      "insight": "Show the 3-tier architecture (Access, Business, Data) with 12 services arranged by layer, making the tier boundaries and service groupings visually distinct"
    },
    {
      "id": "connection-type-encoding",
      "insight": "Encode connection types using visual differentiation: solid lines for synchronous calls, dashed lines for asynchronous/message-queue-mediated calls, and distinct colors or line weights for service-mesh sidecar proxied connections"
    },
    {
      "id": "dependency-complexity-hotspots",
      "insight": "Highlight services with the highest number of inbound and outbound connections to reveal dependency complexity hotspots, especially at the Business layer"
    },
    {
      "id": "infrastructure-components",
      "insight": "Visually distinguish shared infrastructure components (message queue, cache, databases) from application services, showing how multiple services converge on these shared resources"
    },
    {
      "id": "observability-overlay",
      "insight": "Display observability and service-mesh components (tracing, metrics, logging, sidecar proxies) as an overlay or annotation layer that spans across all three tiers"
    }
  ]
}
